"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[3314],{5801(e){e.exports=JSON.parse('{"title":"\uc0dd\uac01\ubcf4\ub2e4 Skills\ubcf4\ub2e4\ub294 AGENT.md\uac00 \uc911\uc694\ud558\ub2e4","date":"2026-02-09","coverUrl":null,"html":"<h1 data-notion-block-id=\\"2f4e548d-8a8e-80d7-a9ab-d1a9ccf4dba1\\">Beyond the Article: \ud55c \uac78\uc74c \ub354</h1><h2 data-notion-block-id=\\"2fce548d-8a8e-80f4-b86c-f64f13075893\\" id=\\"2fce548d-8a8e-80f4-b86c-f64f13075893\\">\uc0dd\uac01\ubcf4\ub2e4 Skills\ubcf4\ub2e4\ub294 AGENT.md\uac00 \uc911\uc694\ud558\ub2e4</h2><a href=\\"https://vercel.com/blog/agents-md-outperforms-skills-in-our-agent-evals\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://vercel.com/blog/agents-md-outperforms-skills-in-our-agent-evals</a><p data-notion-block-id=\\"2fce548d-8a8e-803d-bba6-d9ca0ec57eed\\">\ubb3c\ub860 Skills.md\uac00 \ud45c\uc900\uc774 \ub41c\uc9c0 \uc5bc\ub9c8 \ub418\uc9c0 \uc54a\uc558\uace0, \uadf8\ub7ec\ubbc0\ub85c \ucf54\ub4dc \uc5d0\uc774\uc804\ud2b8\uc758 AGENT.md(Claude.md)\uc758 \ud65c\uc6a9\ub3c4\uac00 \ub354 \ub192\uc740 \uac83\uc740 \ub2f9\uc5f0\ud55c \uacb0\uacfc\ub85c \uc774\uc5b4\uc9c8 \uc9c0\ub3c4 \ubaa8\ub974\uc9c0\ub9cc, \ud604\uc7ac\uc5d0\ub294 AGENT.md\uac00 \uc911\uc694\ud558\ub2e4\ub294 \uac83\uc744 \ubcf4\uc5ec\uc8fc\ub294, \uadf8\ub9ac\uace0 \uc774\ub97c \uc704\ud574 \uc5b4\ub5bb\uac8c \ud30c\uc77c\uc744 \uad6c\ucd95\ud574\uc57c \ud558\ub294\uc9c0 \ubcf4\uc5ec\uc8fc\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"2fce548d-8a8e-8004-922c-e382f466c732\\" id=\\"2fce548d-8a8e-8004-922c-e382f466c732\\">GraphQL\uc740 \uc0dd\uac01\ubcf4\ub2e4 \ubcc4\ub85c\uc774\ub2e4.</h2><a href=\\"https://johnjames.blog/posts/graphql-the-enterprise-honeymoon-is-over\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://johnjames.blog/posts/graphql-the-enterprise-honeymoon-is-over</a><p data-notion-block-id=\\"2f8e548d-8a8e-8070-9fa5-eca7b19b7eb1\\">GraphQL\uc774 \ud574\uacb0\ud558\uace0\uc790 \ud588\ub358 \uc774\ub860\uc0c1 \ubb38\uc81c\ub4e4\uc774 \uc788\uc5c8\uc9c0\ub9cc, \uc0dd\uac01\ubcf4\ub2e4 \uc5ec\ub7ec\ubb38\uc81c\uac00 \uc788\uc5c8\uace0 \uadf8\ub807\uae30\uc5d0 \uc0dd\uac01\ubcf4\ub2e4 GraphQL\uc774 \ubcc4\ub85c\ub77c\ub294 \uc8fc\uc7a5\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \ud558\uc9c0\ub9cc 4XX\ub97c \ubb34\uc870\uac74 \ud074\ub77c\uc774\uc5b8\ud2b8 \uc624\ub958\ub97c \uc758\ubbf8\ud55c\ub2e4\ub358\uac00(\uacbd\uc6b0\uc5d0 \ub530\ub77c 2XX\ub97c \ub0b4\ub824\uc8fc\uace0 \uc5d0\ub7ec\ub77c\uace0 \ud558\ub294 \uacbd\uc6b0\ub3c4 \uc788\uc73c\ub2c8\uae4c\uc694), \ubaa8\ub450\uac00 \uc544\ub294 GraphQL\uc758 \ucd94\uac00 \ub7ec\ub2dd\ucee4\ube0c(AI\ub97c \ud1b5\ud574 \uc5b4\ub290\uc815\ub3c4 \uc644\ud654\ub420 \uc218 \uc788\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4)\uac19\uc740 \uc5b5\uc9c0\ub85c \ub07c\uc6cc\ub123\uc740 \uac83 \uac19\uc740 \ub2e8\uc810\ub3c4 \uc788\uc9c0\ub9cc, \uc9c0\ub098\uce60 \uc218 \uc788\ub294 \ub2e8\uc810\ub4e4\uc744 \uc9da\uc5b4\uc8fc\ub294 \uae00\uc774\ubbc0\ub85c \ud55c \ubc88 \ubcf4\uc2dc\ub294 \uac83\uc744 \ucd94\ucc9c\ub4dc\ub9bd\ub2c8\ub2e4. <a href=\\"https://ones-to-watch.ethansup.net/news/post/a5902c7d-ee33-4db6-aaea-ea4820a7562f#74f4eb91-3e62-42f4-a1e1-4e4d6ad3375c\\">GraphQL\uc740 \uc815\ub9d0 \uc4f0\ub808\uae30\uc778\uac00\uc694?</a>\ub3c4\uc694!</p><h2 data-notion-block-id=\\"2fce548d-8a8e-80b9-8f40-d0d715e3023a\\" id=\\"2fce548d-8a8e-80b9-8f40-d0d715e3023a\\">TypeScript\ub97c Go\ub85c \ubc14\uafe8\ub2e4. \uadf8\ub85c \ubd80\ud130 \ubc30\uc6b8 \uc218 \uc788\ub294 \uad50\ud6c8</h2><a href=\\"https://github.blog/developer-skills/programming-languages-and-frameworks/7-learnings-from-anders-hejlsberg-the-architect-behind-c-and-typescript/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://github.blog/developer-skills/programming-languages-and-frameworks/7-learnings-from-anders-hejlsberg-the-architect-behind-c-and-typescript/</a><p data-notion-block-id=\\"2f8e548d-8a8e-8074-acb0-cfc1d73bd0c9\\">C# \uc544\ud0a4\ud14d\ud2b8, TypeScript\uc758 \uc124\uacc4\uc790\uc778 \uc564\ub354\uc2a4 \ud5e4\uc77c\uc2a4\ubca0\ub9ac\ub97c \uc778\ud130\ubdf0\ud558\uba74\uc11c C#\uacfc TypeScript\uc5d0\uc11c \ubc30\uc6b4 \uad50\ud6c8\uc744 \uc778\ud130\ubdf0\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \ubaa8\ub4e0 \uac1c\ubc1c\uc790\uc5d0\uac8c \uc801\uc6a9\ub418\uc9c0 \uc54a\uc744 \uc218\ub3c4 \uc788\uaca0\uc9c0\ub9cc, \ubaa8\ub4e0 \uac1c\ubc1c\uc790\uc5d0\uac8c \uad50\ud6c8\uc744 \uc904 \uc218 \uc788\ub294, \ube60\ub978 \ud53c\ub4dc\ubc31, \ud22c\uba85\uc131\uc758 \uc7a5\uc810, \uadf8\ub9ac\uace0 \uae30\uc874 \uc0dd\ud0dc\uacc4\uc758 \uc874\uc911\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4. AI\ub97c \ub9ce\uc774 \uc0ac\uc6a9\ud558\ub354\ub77c\ub3c4, AI\uac00 \ubc1c\uc804\ud558\ub354\ub77c\ub3c4, \uadf8 \uadfc\uac04\uc778 \ud328\ud134\uc740 \ubc14\ub00c\uc9c0 \uc54a\uc74c\uc744 \uac15\uc870\ud558\uace0, \ub17c\ub9ac\uc801\uc73c\ub85c \uc124\uba85\ud558\ubbc0\ub85c \ud55c \ubc88 \ubcf4\uc2dc\uae38 \ucd94\ucc9c\ub4dc\ub9bd\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"2fce548d-8a8e-8043-b3e4-edfca5401f45\\" id=\\"2fce548d-8a8e-8043-b3e4-edfca5401f45\\">\uc77c\ubc18\uc801\uc778 CSS Layout \uc774\ud574\ud558\uae30</h2><a href=\\"https://polypane.app/blog/understanding-the-fundamentals-of-css-layout/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://polypane.app/blog/understanding-the-fundamentals-of-css-layout/</a><p data-notion-block-id=\\"2fde548d-8a8e-804c-bfab-c3d02e20bef4\\">\ucc98\uc74c CSS\ub97c \uc0ac\uc6a9\ud558\uac8c \ub418\uba74 \uc774\ud574\ud558\uae30 \uc5b4\ub824\uc6b4 \ubd80\ubd84\uc740 Layout\uc5d0 \ub300\ud55c \ubd80\ubd84\uc785\ub2c8\ub2e4. \ubb3c\ub860 flexbox\ub97c \ubaa8\ub4e0 \uacf3\uc5d0 \uc0ac\uc6a9\ud558\uba74 \ub418\uae34 \ud558\uc9c0\ub9cc, \ubaa8\ub4e0 \uacf3\uc5d0 \uc801\uc6a9\ud560 \uc218\ub294 \uc5c6\uc73c\ub2c8\uae4c\uc694. \uae30\ubcf8 Layout flow\ub294 \uc5b4\ub5bb\uac8c \ub418\ub294\uc9c0, \uadf8\ub9ac\uace0 \uc5b4\ub5bb\uac8c \uc77c\ubc18\uc801\uc73c\ub85c \ub5a0\uc62c\ub9ac\ub294 Layout \uc124\uc815\uc744 \uc5b4\ub5bb\uac8c \uc801\uc6a9\ud558\ub294\uc9c0 \ubcf4\uc5ec\uc8fc\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h1 data-notion-block-id=\\"2f4e548d-8a8e-8096-8b6d-c4bb527ed66a\\">Straight to the Article: \ube5b\ub098\ub294 \uc778\uc0ac\uc774\ud2b8</h1><h2 data-notion-block-id=\\"2fce548d-8a8e-8005-8ed9-f9b4de168daf\\" id=\\"2fce548d-8a8e-8005-8ed9-f9b4de168daf\\">\uc65c Info Tips \ucef4\ud3ec\ub10c\ud2b8\uac00 \ubcc4\ub85c\uc77c\uae4c?</h2><a href=\\"https://www.nngroup.com/articles/info-tips-bad/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.nngroup.com/articles/info-tips-bad/</a><p data-notion-block-id=\\"2fde548d-8a8e-801e-aa89-c6ea40e02137\\">Info tips\uac00 \ubb34\uc2a8 \ucef4\ud3ec\ub10c\ud2b8\uc774\uace0, \uc5b4\ub5a4 \uacbd\uc6b0\uc5d0\ub9cc \uc774 \ucef4\ud3ec\ub10c\ud2b8\ub97c \uc368\uc57c \ud558\ub294\uc9c0, \uadf8\ub9ac\uace0 \uc5b4\ub5a4 \uacbd\uc6b0\uc5d0 \ubcc4\ub85c\uc778\uc9c0 \uc18c\uac1c\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"2fde548d-8a8e-80be-bd9d-c1ca74ffb57a\\" id=\\"2fde548d-8a8e-80be-bd9d-c1ca74ffb57a\\">Soft delete \uad6c\ud604\ud560\ub54c \uc720\uc758\ud560 \uc810</h2><a href=\\"https://atlas9.dev/blog/soft-delete.html\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://atlas9.dev/blog/soft-delete.html</a><p data-notion-block-id=\\"2fce548d-8a8e-80a0-bef8-d96be46800e7\\">\uac04\ub2e8\ud558\uac8c Soft delete\ub97c \uad6c\ud604\ud560 \ub54c \ub2e8\uc810, \uadf8\ub9ac\uace0 \uc774\ub97c \uc5b4\ub5bb\uac8c \ub300\uccb4\ud560 \uc218 \uc788\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"2f7e548d-8a8e-80f8-a1c6-d3382ade6968\\" id=\\"2f7e548d-8a8e-80f8-a1c6-d3382ade6968\\">Single Flight mutation\uc740 \ubb34\uc5c7\uc77c\uae4c?</h2><a href=\\"https://frontendmasters.com/blog/single-flight-mutations-in-tanstack-start-part-1/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://frontendmasters.com/blog/single-flight-mutations-in-tanstack-start-part-1/</a><p data-notion-block-id=\\"2fde548d-8a8e-80ff-bd14-e858ce8a99e4\\">2\uac1c\uc758 \ud30c\ud2b8\ub85c Single Flight mutation\uc774 \ubb34\uc5c7\uc778\uc9c0 \uc54c\uc544\ubcf4\uace0, Single Flight mutation\uc744 Tanstack Start\uc640 Tanstack Query\uc758 \uc870\ud569\uc73c\ub85c \uad6c\ud604\ud574\ubcf4\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"2fce548d-8a8e-80b0-b4af-d9033a3d8ebb\\" id=\\"2fce548d-8a8e-80b0-b4af-d9033a3d8ebb\\">FLIP \uc560\ub2c8\uba54\uc774\uc158\uc758 \ub300\uccb4, AIM\uc774 \uc628\ub2e4.</h2><a href=\\"https://nerdy.dev/anchor-interpolated-morphing\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://nerdy.dev/anchor-interpolated-morphing</a><h2 data-notion-block-id=\\"2fde548d-8a8e-806c-96b8-f4f65f77b0f3\\" id=\\"2fde548d-8a8e-806c-96b8-f4f65f77b0f3\\">\ub9c8\uc6b0\uc2a4\ub97c \ub118\uc5b4, \ubaa8\ubc14\uc77c \uc13c\uc11c\ub97c \ud45c\ud604\ud558\uae30</h2><a href=\\"https://frontendmasters.com/blog/beyond-the-mouse-animating-with-mobile-accelerometers/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://frontendmasters.com/blog/beyond-the-mouse-animating-with-mobile-accelerometers/</a><h2 data-notion-block-id=\\"2fde548d-8a8e-80b9-9571-cfbea2531380\\" id=\\"2fde548d-8a8e-80b9-9571-cfbea2531380\\">React Native\uc5d0\uc11c CSS <code>clip-path()</code>\ub97c \uad6c\ud604\ud558\uae30</h2><a href=\\"https://www.callstack.com/blog/bringing-css-clipping-to-react-native\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.callstack.com/blog/bringing-css-clipping-to-react-native</a><h1 data-notion-block-id=\\"2f4e548d-8a8e-802f-8395-f5b533e38e82\\">Fresh Finds: \ub193\uce58\uc9c0 \ub9d0\uc544\uc57c \ud560 \uc18c\uc2dd</h1><a href=\\"https://stylexjs.com/blog/a-new-year-2026\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://stylexjs.com/blog/a-new-year-2026</a><p data-notion-block-id=\\"2fce548d-8a8e-8072-91aa-f9b3f61b6b30\\">Stylex\uac00 \uc5b4\ub290 \ubc29\ud5a5\uc73c\ub85c \ubc1c\uc804\ud560 \uac83\uc778\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><a href=\\"https://blog.logrocket.com/css-in-2026/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blog.logrocket.com/css-in-2026/</a><p data-notion-block-id=\\"2fce548d-8a8e-80fe-b4cb-d4ee76ff2c70\\">2026\ub144\uc5d0 \uc0c8\ub86d\uac8c \ub2e4\uac00\uc624\ub294 CSS \uc18d\uc131\ub4e4\uc744 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><a href=\\"https://voidzero.dev/posts/announcing-rolldown-rc\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://voidzero.dev/posts/announcing-rolldown-rc</a><p data-notion-block-id=\\"2fce548d-8a8e-8096-af6c-ee0fa50c30fa\\">Rolldown 1\ubc84\uc804 \ucd9c\uc2dc \uc18c\uc2dd\uc774 \ub2e4\uac00\uc654\ub2e4\ub294 \uc18c\uc2dd\uc785\ub2c8\ub2e4.</p><a href=\\"https://yarn6.netlify.app/blog/2026-01-28-yarn-6-preview/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://yarn6.netlify.app/blog/2026-01-28-yarn-6-preview/</a><p data-notion-block-id=\\"2fce548d-8a8e-8025-8c81-e19796a9e9b5\\">Yarn berry\uac00 6\ubc84\uc804\uc774 \ub418\uba74\uc11c Rust\ub85c \ud3ec\ud305\ud558\uac8c \ub418\uace0, \uadf8\ub97c \uc0ac\uc6a9\ud560 \uc218 \uc788\uac8c Preview \ubc84\uc804\uc744 \uc18c\uac1c\ud55c\ub2e4\ub294 \uc18c\uc2dd\uc785\ub2c8\ub2e4.</p><a href=\\"https://github.com/unjs/unplugin\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://github.com/unjs/unplugin</a><p data-notion-block-id=\\"2fce548d-8a8e-8006-83fe-d7a90c8a2249\\">\ubc88\ub4e4\ub7ec\uc640 \uc0c1\uad00\uc5c6\uc774 \ubaa8\ub4e0 \ubc88\ub4e4\ub7ec\uc5d0\uc11c\uc758 \ud50c\ub7ec\uadf8\uc778\uc744 \uc0ac\uc6a9\ud560 \uc218 \uc788\ub3c4\ub85d \uc124\uacc4\ub41c \ud50c\ub7ec\uadf8\uc778 \uc81c\uc791 \ud0b7\uc778 unplugin\uc785\ub2c8\ub2e4.</p>"}')}}]);